import { test } from 'node:test';
import assert from 'node:assert/strict';
import { slugify } from './slugify.js';

test('lower-cases and joins words with hyphens', () => {
  assert.equal(slugify('Snow Crash'), 'snow-crash');
});

test('collapses runs of separators into one hyphen', () => {
  assert.equal(slugify('Dune:  Part   Two!'), 'dune-part-two');
});

test('trims separators from both ends', () => {
  assert.equal(slugify('  Dune: Part Two! '), 'dune-part-two');
});

test('throws a TypeError for non-string input', () => {
  assert.throws(() => slugify(42), TypeError);
});
